window.docContents[109].resolve({"/#getting-to-know-conveniences":{"contents":"Lean contains a number of convenience features that make programs much more concise.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Functional Programming in Lean\u0009Getting to Know Lean","header":"1.8. Additional Conveniences","id":"/#getting-to-know-conveniences"},"/#next-steps":{"contents":"This book introduces the very basics of functional programming in Lean, including a tiny amount of interactive theorem proving.\nUsing dependently-typed functional languages like Lean is a deep topic, and much can be said.\nDepending on your interests, the following resources might be useful for learning Lean 4.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Functional Programming in Lean","header":"9. Next Steps","id":"/#next-steps"}});